import Foundation

/// A self-contained, cache-free phone form. The fragment is never sent in a URL request or referrer.
/// 手机页不加载第三方资源；会话片段只在内存中用于提交头，不含 API Key。
enum ReadPicoWeReadPhoneSetupPage {
    static let html = #"""
<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="color-scheme" content="light dark"><meta name="referrer" content="no-referrer"><title>微信读书授权 · 多屏灵犀</title>
<style>
:root{font:17px/1.6 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color-scheme:light dark;--bg:#f5f5f7;--surface:#fff;--text:#1d1d1f;--secondary:#515154;--border:#c7c7cc;--accent:#0062d4;--button:#0062d4}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text)}main{max-width:560px;margin:auto;padding:36px 22px calc(32px + env(safe-area-inset-bottom))}header p{color:var(--secondary);margin-top:8px}h1{font-size:28px;line-height:1.25;letter-spacing:-.6px;margin:10px 0}h2{font-size:19px;margin:0 0 10px}.brand{font-size:14px;font-weight:600;color:var(--secondary)}section{background:var(--surface);padding:22px;border-radius:18px;margin:18px 0}p{margin:10px 0}a{color:var(--accent)}a.button,button{display:block;text-align:center;background:var(--button);color:white;border:0;border-radius:12px;font:inherit;font-weight:600;line-height:1.4;min-height:48px;padding:12px 16px;text-decoration:none;cursor:pointer;width:100%}label{display:block;font-weight:600;margin:16px 0 7px}input{display:block;width:100%;padding:13px 12px;min-height:48px;border:1px solid var(--border);border-radius:10px;font:17px/1.4 ui-monospace,monospace;background:var(--surface);color:var(--text)}input:focus,button:focus-visible,a:focus-visible{outline:3px solid var(--accent);outline-offset:3px}.secondary{color:var(--secondary);font-size:14px}.reveal{display:inline-block;padding:8px 0;background:none;color:var(--accent);width:auto;text-align:left;font-size:15px;min-height:44px}.status{min-height:1.5em;margin-top:14px}.error{font-weight:600}.success{display:none}button:disabled{opacity:.55;cursor:default}.step{color:var(--secondary);font-variant-numeric:tabular-nums;margin-right:8px}footer{color:var(--secondary);font-size:14px} @media(prefers-color-scheme:dark){:root{--bg:#161617;--surface:#242426;--text:#f5f5f7;--secondary:#b6b6bb;--border:#626268;--accent:#368dff}a.button,button[type=submit]{color:#fff}}@media(prefers-reduced-motion:no-preference){button{transition:opacity .15s}}
</style></head><body><main><header><div class="brand">多屏灵犀 · 小纸 Pico</div><h1>连接微信读书</h1><p>在手机上完成授权，再回到 Mac 选择书籍和笔记。</p></header><div id="setup"><section><h2><span class="step">1</span>获取官方 API Key</h2><p>打开微信读书官方页面，登录后创建并复制 <strong>wrk-</strong> 开头的 API Key，再返回本页。</p><a class="button" href="https://weread.qq.com/r/weread-skills" target="_blank" rel="noopener noreferrer">打开微信读书官方授权页 ↗</a></section><section><h2><span class="step">2</span>保存到这台 Mac</h2><form id="form" autocomplete="off"><label for="key">API Key</label><input id="key" name="api_key" type="password" autocomplete="off" autocapitalize="none" spellcheck="false" placeholder="wrk-…" maxlength="512" required aria-describedby="key-help"><button class="reveal" type="button" id="reveal" aria-controls="key" aria-pressed="false">显示密钥</button><p id="key-help" class="secondary">密钥仅加密保存在本机，不会传入 Pico。此临时页面使用本地 HTTP，请仅在可信的同一局域网填写。</p><button id="submit" type="submit">保存授权到 Mac</button><p id="status" class="status" role="status" aria-live="polite"></p></form></section><section><h2><span class="step">3</span>回到多屏灵犀同步</h2><p>点击“读取书架”，勾选书籍并读取笔记，核对后同步到 Pico。</p><p class="secondary">支持个人划线和想法，暂不支持整书正文下载。</p></section></div><section class="success" id="success" tabindex="-1"><h2>授权已保存</h2><p>可以关闭此页，回到 Mac 点击“读取书架”，继续选择要同步的笔记。</p><p class="secondary">本次临时配置入口已关闭。如需更换授权，请在多屏灵犀重新打开手机授权。</p></section><footer>二维码十分钟内有效，保存成功或关闭 Mac 引导后失效。</footer></main>
<script>
(()=>{'use strict';let token=location.hash.slice(1);history.replaceState(null,'',location.pathname);const form=document.getElementById('form'),key=document.getElementById('key'),submit=document.getElementById('submit'),status=document.getElementById('status'),reveal=document.getElementById('reveal');function message(text,error){status.textContent=text;status.classList.toggle('error',!!error)}if(!/^[a-f0-9]{64}$/.test(token)){submit.disabled=true;message('此链接缺少授权会话。请回到 Mac 重新扫码。',true)}reveal.addEventListener('click',()=>{const visible=key.type==='password';key.type=visible?'text':'password';reveal.textContent=visible?'隐藏密钥':'显示密钥';reveal.setAttribute('aria-pressed',String(visible))});form.addEventListener('submit',async event=>{event.preventDefault();if(submit.disabled)return;const value=key.value.trim();if(!/^wrk-[\x21-\x7e]{4,508}$/.test(value)){message('请粘贴完整的 wrk- API Key。',true);key.focus();return}submit.disabled=true;key.disabled=true;message('正在保存到 Mac…',false);const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),15000);try{const response=await fetch('/api/weread/authorize',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+token},body:JSON.stringify({api_key:value}),credentials:'omit',cache:'no-store',redirect:'error',signal:controller.signal});const result=await response.json();if(!response.ok){message(result.message||'未能保存，请回到 Mac 检查授权页面。',true);if(response.status===410||response.status===401)token='';return}key.value='';token='';document.getElementById('setup').hidden=true;document.getElementById('success').style.display='block';document.getElementById('success').focus()}catch(_){message('无法连接这台 Mac。请确认处于同一网络，并在 Mac 上重新打开手机授权。',true)}finally{clearTimeout(timer);key.disabled=false;submit.disabled=!token}});window.addEventListener('pagehide',()=>{key.value=''});})();
</script></body></html>
"""#
}
